11→// Reads SES (Standardized Emissions Schema) compliant NetCDF files,
12→// or non-standard files adapted through a DatasetDescriptor.
13→class SESReader {
14→ public:
15→  SESReader() = default;
16→  ~SESReader() { Close(); }
17→
18→  // Non-copyable (owns a NetCDF file handle)
19→  SESReader(const SESReader&) = delete;
20→  SESReader& operator=(const SESReader&) = delete;
21→  SESReader(SESReader&& other) noexcept;
22→  SESReader& operator=(SESReader&& other) noexcept;
23→
24→  // Open a NetCDF file. If descriptor is provided, use it for non-SES files.
25→  // If the file is SES-compliant, descriptor overrides are ignored.
26→  void Open(const std::string& file_path,
27→            const DatasetDescriptor& descriptor = DatasetDescriptor::Default());
28→
29→  void Close();
30→
31→  // Discover available species in the file
32→  std::vector<std::string> QuerySpecies() const;
33→
34→  // Get the number of time steps in the file
35→  int NumTimeSteps() const { return n_time_steps_; }
36→
37→  // Get time values (in seconds since reference, or as stored)
38→  std::vector<double> GetTimeValues() const;
39→
40→  // Read flux data for all species at a given time index.
41→  // Returns data as (n_species * n_cells) array in kg/m^2/s.
42→  void ReadFlux(int time_index,
43→                const std::vector<std::string>& species_names,
44→                std::vector<Real>& flux_out,
45→                int& n_cells_out) const;
46→
47→  bool IsOpen() const { return ncid_ >= 0; }
48→
49→  int NumCells() const { return n_cells_; }
50→
51→ private:
52→  int ncid_ = -1;
53→  std::string file_path_;
54→  DatasetDescriptor descriptor_;
55→  bool is_ses_compliant_ = false;
56→  std::string ses_version_;   // Detected SES/MIEM version string
57→  int n_time_steps_ = 0;
58→  int n_cells_ = 0;
59→  std::vector<std::string> available_species_;
60→
61→  void DetectFormat();
62→  void DiscoverSpecies();
63→  std::string CanonicalName(const std::string& var_name) const;
64→};
65→
66→}  // namespace miem
