11→struct EmisState {
12→  int n_species = 0;
13→  int n_cells = 0;
14→  int n_vert_levels = 0;
15→
16→  // Surface fluxes: (n_species * n_cells) in kg/m^2/s
17→  // Layout: species-major, i.e. flux[species_idx * n_cells + cell_idx]
18→  std::vector<Real> surface_flux;
19→
20→  // Volumetric tendencies: (n_species * n_vert_levels * n_cells) in kg/kg/s
21→  // Layout: tendency[species_idx * n_vert_levels * n_cells + level_idx * n_cells + cell_idx]
22→  std::vector<Real> tendency;
23→
24→  // Maps emission species index to host chemistry species index
25→  std::vector<int> emis_to_chem_idx;
26→
27→  // Injection layer for each species (0 = surface)
28→  std::vector<int> injection_layer;
29→
30→  // Species names for this emission state
31→  std::vector<std::string> species_names;
32→
33→  // Per-sector surface fluxes: sector_name -> (n_species * n_cells) array
34→  std::map<std::string, std::vector<Real>> sector_fluxes;
35→
36→  // Sector names in insertion order
37→  std::vector<std::string> sector_names;
38→
39→  EmisState() = default;
40→  EmisState(int n_species, int n_cells, int n_vert_levels);
41→
42→  void Resize(int n_species, int n_cells, int n_vert_levels);
43→  void Zero();
44→
45→  bool HasSectors() const { return !sector_fluxes.empty(); }
46→  const std::vector<Real>& GetSectorFlux(const std::string& sector) const;
47→
48→  Real* SurfaceFluxData() { return surface_flux.data(); }
49→  const Real* SurfaceFluxData() const { return surface_flux.data(); }
50→
51→  Real* TendencyData() { return tendency.data(); }
52→  const Real* TendencyData() const { return tendency.data(); }
53→
54→  int* EmisToChemIdxData() { return emis_to_chem_idx.data(); }
55→  const int* EmisToChemIdxData() const { return emis_to_chem_idx.data(); }
56→};
57→
58→}  // namespace miem
