10→// Describes how to interpret a non-SES-compliant NetCDF file.
11→// Fields provide overrides that normalize the file to SES conventions.
12→struct DatasetDescriptor {
13→  std::string variable_prefix = "emi_";        // Default SES prefix
14→  std::string flux_units = "kg m-2 s-1";
15→  Real unit_conversion_factor = 1.0;           // Multiply raw data by this
16→  std::string time_dimension = "time";
17→  std::string cell_dimension = "n_cells";
18→  std::string grid_description;
19→
20→  // Rename map: original_var_name -> canonical_name
21→  std::map<std::string, std::string> species_rename;
22→
23→  // Load descriptor overrides from a YAML file
24→  static DatasetDescriptor FromYAML(const std::string& yaml_path);
25→
26→  // Returns the default SES descriptor (no overrides)
27→  static DatasetDescriptor Default();
28→};
