 23→SESReader::SESReader(SESReader&& other) noexcept
 24→    : ncid_(other.ncid_),
 25→      file_path_(std::move(other.file_path_)),
 26→      descriptor_(std::move(other.descriptor_)),
 27→      is_ses_compliant_(other.is_ses_compliant_),
 28→      ses_version_(std::move(other.ses_version_)),
 29→      n_time_steps_(other.n_time_steps_),
 30→      n_cells_(other.n_cells_),
 31→      available_species_(std::move(other.available_species_)) {
 32→  other.ncid_ = -1;
 33→}
 34→
 35→SESReader& SESReader::operator=(SESReader&& other) noexcept {
 36→  if (this != &other) {
 37→    Close();
 38→    ncid_ = other.ncid_;
 39→    file_path_ = std::move(other.file_path_);
 40→    descriptor_ = std::move(other.descriptor_);
 41→    is_ses_compliant_ = other.is_ses_compliant_;
 42→    ses_version_ = std::move(other.ses_version_);
 43→    n_time_steps_ = other.n_time_steps_;
 44→    n_cells_ = other.n_cells_;
 45→    available_species_ = std::move(other.available_species_);
 46→    other.ncid_ = -1;
 47→  }
 48→  return *this;
 49→}
 50→
 51→void SESReader::Open(const std::string& file_path,
 52→                     const DatasetDescriptor& descriptor) {
 53→  if (ncid_ >= 0) {
 54→    Close();
 55→  }
 56→
 57→  file_path_ = file_path;
 58→  descriptor_ = descriptor;
 59→
 60→  int status = nc_open(file_path.c_str(), NC_NOWRITE, &ncid_);
 61→  if (status != NC_NOERR) {
 62→    throw IOError("Failed to open NetCDF file: " + file_path +
 63→                  " — " + nc_strerror(status));
 64→  }
 65→
 66→  DetectFormat();
 67→  DiscoverSpecies();
 68→}
 69→
 70→void SESReader::Close() {
 71→  if (ncid_ >= 0) {
 72→    nc_close(ncid_);
 73→    ncid_ = -1;
 74→  }
 75→  available_species_.clear();
 76→  n_time_steps_ = 0;
 77→  n_cells_ = 0;
 78→}
