 80→void SESReader::DetectFormat() {
 81→  // Check for SES compliance via ses_version global attribute
 82→  is_ses_compliant_ = false;
 83→  ses_version_.clear();
 84→
 85→  size_t att_len = 0;
 86→  int status = nc_inq_attlen(ncid_, NC_GLOBAL, "ses_version", &att_len);
 87→  if (status == NC_NOERR && att_len < 256) {
 88→    std::vector<char> buf(att_len + 1, '\0');
 89→    status = nc_get_att_text(ncid_, NC_GLOBAL, "ses_version", buf.data());
 90→    if (status == NC_NOERR) {
 91→      ses_version_ = std::string(buf.data(), att_len);
 92→      is_ses_compliant_ = true;
 93→    }
 94→  }
 95→
 96→  // Get time dimension
 97→  int time_dim_id;
 98→  const std::string& time_dim_name =
 99→      is_ses_compliant_ ? "time" : descriptor_.time_dimension;
100→  status = nc_inq_dimid(ncid_, time_dim_name.c_str(), &time_dim_id);
101→  if (status == NC_NOERR) {
102→    size_t time_len;
103→    NC_CHECK(nc_inq_dimlen(ncid_, time_dim_id, &time_len));
104→    n_time_steps_ = static_cast<int>(time_len);
105→  } else {
106→    n_time_steps_ = 1;  // No time dimension; treat as single snapshot
107→  }
108→
109→  // Get cell dimension
110→  int cell_dim_id;
111→  const std::string& cell_dim_name =
112→      is_ses_compliant_ ? "n_cells" : descriptor_.cell_dimension;
113→  status = nc_inq_dimid(ncid_, cell_dim_name.c_str(), &cell_dim_id);
114→  if (status != NC_NOERR) {
115→    throw IOError("Cannot find cell dimension '" + cell_dim_name +
116→                  "' in file: " + file_path_);
117→  }
118→  size_t cell_len;
119→  NC_CHECK(nc_inq_dimlen(ncid_, cell_dim_id, &cell_len));
120→  n_cells_ = static_cast<int>(cell_len);
121→}
