123→void SESReader::DiscoverSpecies() {
124→  available_species_.clear();
125→
126→  int n_vars;
127→  NC_CHECK(nc_inq_nvars(ncid_, &n_vars));
128→
129→  const std::string& prefix =
130→      is_ses_compliant_ ? "emi_" : descriptor_.variable_prefix;
131→
132→  for (int varid = 0; varid < n_vars; ++varid) {
133→    char var_name[NC_MAX_NAME + 1];
134→    NC_CHECK(nc_inq_varname(ncid_, varid, var_name));
135→
136→    std::string name(var_name);
137→    if (name.substr(0, prefix.size()) == prefix) {
138→      std::string species = CanonicalName(name);
139→      available_species_.push_back(species);
140→    }
141→  }
142→}
143→
144→std::string SESReader::CanonicalName(const std::string& var_name) const {
145→  // Check descriptor rename map first
146→  auto it = descriptor_.species_rename.find(var_name);
147→  if (it != descriptor_.species_rename.end()) {
148→    // The rename target should be in emi_X format; strip prefix
149→    const std::string& renamed = it->second;
150→    if (renamed.substr(0, 4) == "emi_") {
151→      return renamed.substr(4);
152→    }
153→    return renamed;
154→  }
155→
156→  // Strip the variable prefix to get species name
157→  const std::string& prefix =
158→      is_ses_compliant_ ? "emi_" : descriptor_.variable_prefix;
159→  if (var_name.substr(0, prefix.size()) == prefix) {
160→    return var_name.substr(prefix.size());
161→  }
162→  return var_name;
163→}
