171→// Parse CF time units string like "days since 2000-01-01" or
172→// "seconds since 1970-01-01 00:00:00" into a multiplier (to seconds)
173→// and a reference epoch (in seconds since Unix epoch).
174→bool ParseCFTimeUnits(const std::string& units_str,
175→                      double& multiplier, double& ref_epoch) {
176→  // Pattern: "<unit> since <date> [<time>]"
177→  std::regex cf_pattern(
178→      R"((\w+)\s+since\s+(\d{4})-(\d{1,2})-(\d{1,2})(?:\s+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?)");
179→  std::smatch match;
180→  if (!std::regex_search(units_str, match, cf_pattern)) {
181→    return false;
182→  }
183→
184→  std::string unit = match[1].str();
185→  int year = std::stoi(match[2].str());
186→  int month = std::stoi(match[3].str());
187→  int day = std::stoi(match[4].str());
188→  int hour = match[5].matched ? std::stoi(match[5].str()) : 0;
189→  int minute = match[6].matched ? std::stoi(match[6].str()) : 0;
190→  int second = match[7].matched ? std::stoi(match[7].str()) : 0;
191→
192→  // Unit to seconds multiplier
193→  if (unit == "seconds" || unit == "second" || unit == "s") {
194→    multiplier = 1.0;
195→  } else if (unit == "minutes" || unit == "minute") {
196→    multiplier = 60.0;
197→  } else if (unit == "hours" || unit == "hour" || unit == "h") {
198→    multiplier = 3600.0;
199→  } else if (unit == "days" || unit == "day" || unit == "d") {
200→    multiplier = 86400.0;
201→  } else {
202→    return false;
203→  }
204→
205→  // Convert reference date to seconds since Unix epoch
206→  std::tm ref_tm{};
207→  ref_tm.tm_year = year - 1900;
208→  ref_tm.tm_mon = month - 1;
209→  ref_tm.tm_mday = day;
210→  ref_tm.tm_hour = hour;
211→  ref_tm.tm_min = minute;
212→  ref_tm.tm_sec = second;
213→  ref_epoch = static_cast<double>(timegm(&ref_tm));
214→
215→  return true;
216→}
