220→std::vector<double> SESReader::GetTimeValues() const {
221→  std::vector<double> times(n_time_steps_, 0.0);
222→
223→  int time_varid;
224→  const std::string& time_var_name =
225→      is_ses_compliant_ ? "time" : descriptor_.time_dimension;
226→  int status = nc_inq_varid(ncid_, time_var_name.c_str(), &time_varid);
227→  if (status != NC_NOERR) {
228→    return times;
229→  }
230→
231→  NC_CHECK(nc_get_var_double(ncid_, time_varid, times.data()));
232→
233→  // Read CF units attribute and convert to seconds since Unix epoch
234→  size_t units_len = 0;
235→  status = nc_inq_attlen(ncid_, time_varid, "units", &units_len);
236→  if (status == NC_NOERR && units_len > 0 && units_len < 1024) {
237→    std::vector<char> units_buf(units_len + 1, '\0');
238→    nc_get_att_text(ncid_, time_varid, "units", units_buf.data());
239→    std::string units_str(units_buf.data(), units_len);
240→
241→    double multiplier = 1.0;
242→    double ref_epoch = 0.0;
243→    if (ParseCFTimeUnits(units_str, multiplier, ref_epoch)) {
244→      for (auto& t : times) {
245→        t = t * multiplier + ref_epoch;
246→      }
247→    }
248→  }
249→
250→  return times;
251→}
252→
253→void SESReader::ReadFlux(int time_index,
254→                         const std::vector<std::string>& species_names,
255→                         std::vector<Real>& flux_out,
256→                         int& n_cells_out) const {
257→  if (ncid_ < 0) {
258→    throw IOError("SESReader: file not open");
259→  }
260→
261→  n_cells_out = n_cells_;
262→  int n_species = static_cast<int>(species_names.size());
263→  flux_out.resize(static_cast<size_t>(n_species) * n_cells_, 0.0);
264→
265→  const std::string& prefix =
266→      is_ses_compliant_ ? "emi_" : descriptor_.variable_prefix;
267→
268→  for (int isp = 0; isp < n_species; ++isp) {
269→    // Build variable name from species name
270→    std::string var_name = prefix + species_names[isp];
271→
272→    // Check if descriptor has a reverse rename
273→    // (we need to map canonical name back to file variable name)
274→    if (!is_ses_compliant_) {
275→      for (const auto& [file_var, canonical] : descriptor_.species_rename) {
276→        std::string canon_species =
277→            (canonical.substr(0, 4) == "emi_") ? canonical.substr(4) : canonical;
278→        if (canon_species == species_names[isp]) {
279→          var_name = file_var;
280→          break;
281→        }
282→      }
283→    }
284→
285→    int varid;
286→    int status = nc_inq_varid(ncid_, var_name.c_str(), &varid);
287→    if (status != NC_NOERR) {
288→      continue;  // Species not in file; leave as zero
289→    }
290→
291→    // Determine dimensionality
292→    int ndims;
293→    NC_CHECK(nc_inq_varndims(ncid_, varid, &ndims));
294→
295→    std::vector<Real> raw(n_cells_);
296→
297→    if (ndims == 2) {
298→      // (time, n_cells)
299→      size_t start[2] = {static_cast<size_t>(time_index), 0};
300→      size_t count[2] = {1, static_cast<size_t>(n_cells_)};
301→#ifdef MIEM_USE_DOUBLE
302→      NC_CHECK(nc_get_vara_double(ncid_, varid, start, count, raw.data()));
303→#else
304→      NC_CHECK(nc_get_vara_float(ncid_, varid, start, count, raw.data()));
305→#endif
306→    } else if (ndims == 1) {
307→      // (n_cells) — single time step
308→#ifdef MIEM_USE_DOUBLE
309→      NC_CHECK(nc_get_var_double(ncid_, varid, raw.data()));
310→#else
311→      NC_CHECK(nc_get_var_float(ncid_, varid, raw.data()));
312→#endif
313→    }
314→
315→    // Check for fill value / missing value and mask to zero
316→    Real fill_value;
317→    bool has_fill = false;
318→#ifdef MIEM_USE_DOUBLE
319→    double fv;
320→    if (nc_get_att_double(ncid_, varid, "_FillValue", &fv) == NC_NOERR) {
321→      fill_value = fv;
322→      has_fill = true;
323→    }
324→#else
325→    float fv;
326→    if (nc_get_att_float(ncid_, varid, "_FillValue", &fv) == NC_NOERR) {
327→      fill_value = fv;
328→      has_fill = true;
329→    }
330→#endif
331→
332→    // Apply unit conversion and fill value masking
333→    Real conv = descriptor_.unit_conversion_factor;
334→    for (int ic = 0; ic < n_cells_; ++ic) {
335→      Real val = raw[ic];
336→      if (has_fill && val == fill_value) {
337→        val = 0.0;
338→      }
339→      flux_out[isp * n_cells_ + ic] = val * conv;
340→    }
341→  }
342→}
