 31→EmissionsModule::EmissionsModule(const std::string& config_path,
 32→                                 int n_cells, int n_vert_levels)
 33→    : n_cells_(n_cells), n_vert_levels_(n_vert_levels) {
 34→  auto config = MIEMConfig::FromYAML(config_path);
 35→
 36→  // Create sources via factory and collect species
 37→  std::set<std::string> species_set;
 38→  for (const auto& src_config : config.sources) {
 39→    auto source = SourceFactory::Create(src_config);
 40→    auto sp = source->QuerySpecies();
 41→    species_set.insert(sp.begin(), sp.end());
 42→    sources_.push_back({
 43→        std::move(source),
 44→        src_config.category,
 45→        src_config.hierarchy,
 46→        src_config.sector,
 47→        src_config.scaling_factor
 48→    });
 49→  }
 50→
 51→  aggregated_species_ = {species_set.begin(), species_set.end()};
 52→}
