 54→void EmissionsModule::ResolveHostIndices(
 55→    const std::vector<std::string>& host_species,
 56→    std::vector<int>& indices) const {
 57→  indices.resize(aggregated_species_.size(), -1);
 58→
 59→  // Build host species lookup
 60→  std::map<std::string, int> host_map;
 61→  for (int i = 0; i < static_cast<int>(host_species.size()); ++i) {
 62→    host_map[host_species[i]] = i;
 63→  }
 64→
 65→  for (int i = 0; i < static_cast<int>(aggregated_species_.size()); ++i) {
 66→    auto it = host_map.find(aggregated_species_[i]);
 67→    if (it != host_map.end()) {
 68→      indices[i] = it->second;
 69→    }
 70→  }
 71→}
