 73→EmisState EmissionsModule::Run(double time_current,
 74→                               const Real* air_density,
 75→                               const Real* layer_thickness,
 76→                               int n_atm_elements) {
 77→  int n_agg = static_cast<int>(aggregated_species_.size());
 78→  EmisState state(n_agg, n_cells_, n_vert_levels_);
 79→  state.species_names = aggregated_species_;
 80→
 81→  // Build index map for aggregation
 82→  std::map<std::string, int> agg_idx;
 83→  for (int i = 0; i < n_agg; ++i) {
 84→    agg_idx[aggregated_species_[i]] = i;
 85→  }
 86→
 87→  size_t flux_size = static_cast<size_t>(n_agg) * n_cells_;
 88→
 89→  // Per-source flux tagged with metadata for category/hierarchy resolution.
 90→  // Structure: for each source, store its scaled flux.
 91→  struct SourceFlux {
 92→    int category;
 93→    int hierarchy;
 94→    std::string sector;
 95→    std::vector<Real> flux;  // (n_agg * n_cells)
 96→  };
 97→
 98→  std::vector<SourceFlux> source_fluxes;
 99→  source_fluxes.reserve(sources_.size());
100→
101→  for (auto& entry : sources_) {
102→    std::vector<Real> src_flux;
103→    std::vector<std::string> src_species;
104→    entry.source->Update(time_current, n_cells_, src_flux, src_species);
105→
106→    // Map source species into aggregated species space and apply scaling
107→    std::vector<Real> mapped(flux_size, 0.0);
108→    int n_src_sp = static_cast<int>(src_species.size());
109→    for (int isp = 0; isp < n_src_sp; ++isp) {
110→      auto it = agg_idx.find(src_species[isp]);
111→      if (it == agg_idx.end()) continue;
112→      int dst_idx = it->second;
113→
114→      for (int ic = 0; ic < n_cells_; ++ic) {
115→        mapped[dst_idx * n_cells_ + ic] =
116→            src_flux[isp * n_cells_ + ic] * entry.scaling_factor;
117→      }
118→    }
119→
120→    source_fluxes.push_back({
121→        entry.category,
122→        entry.hierarchy,
123→        entry.sector,
124→        std::move(mapped)
125→    });
126→  }
127→
128→  // Collect distinct categories
129→  std::set<int> categories;
130→  for (const auto& sf : source_fluxes) {
131→    categories.insert(sf.category);
132→  }
133→
134→  // Category/hierarchy aggregation:
135→  //   1. Within each category, for each (species, cell), take the flux from
136→  //      the highest-hierarchy source that has non-zero flux.
137→  //   2. Sum across categories.
138→  for (int cat : categories) {
139→    // Gather sources in this category, sorted by hierarchy descending
140→    std::vector<const SourceFlux*> cat_sources;
141→    for (const auto& sf : source_fluxes) {
142→      if (sf.category == cat) {
143→        cat_sources.push_back(&sf);
144→      }
145→    }
146→    std::sort(cat_sources.begin(), cat_sources.end(),
147→              [](const SourceFlux* a, const SourceFlux* b) {
148→                return a->hierarchy > b->hierarchy;
149→              });
150→
151→    // For each species/cell, take the first (highest hierarchy) non-zero value
152→    for (int isp = 0; isp < n_agg; ++isp) {
153→      for (int ic = 0; ic < n_cells_; ++ic) {
154→        size_t idx = static_cast<size_t>(isp) * n_cells_ + ic;
155→        for (const auto* src : cat_sources) {
156→          if (src->flux[idx] != 0.0) {
157→            state.surface_flux[idx] += src->flux[idx];
158→            break;
159→          }
160→        }
161→      }
162→    }
163→  }
164→
165→  // Populate per-sector fluxes for diagnostics
166→  for (const auto& sf : source_fluxes) {
167→    if (sf.sector.empty()) continue;
168→
169→    auto it = state.sector_fluxes.find(sf.sector);
170→    if (it == state.sector_fluxes.end()) {
171→      state.sector_fluxes[sf.sector] = sf.flux;
172→      state.sector_names.push_back(sf.sector);
173→    } else {
174→      // Multiple sources with same sector label: sum them
175→      for (size_t i = 0; i < flux_size; ++i) {
176→        it->second[i] += sf.flux[i];
177→      }
178→    }
179→  }
180→
181→  // Convert surface fluxes to tendencies
182→  FluxConverter::Convert(state, air_density, layer_thickness, n_atm_elements);
183→
184→  return state;
185→}
