 31→std::string OfflineEmissionSource::ResolveFilePath(double time) const {
 32→  std::string pattern = config_.file_pattern;
 33→
 34→  // If no tokens present, return as-is
 35→  if (pattern.find('{') == std::string::npos) {
 36→    return pattern;
 37→  }
 38→
 39→  // Convert time (seconds since epoch) to calendar components
 40→  auto time_t_val = static_cast<std::time_t>(time);
 41→  std::tm tm_val{};
 42→  gmtime_r(&time_t_val, &tm_val);
 43→
 44→  // Expand tokens
 45→  auto replace_token = [&](const std::string& token, const std::string& value) {
 46→    std::string::size_type pos;
 47→    while ((pos = pattern.find(token)) != std::string::npos) {
 48→      pattern.replace(pos, token.size(), value);
 49→    }
 50→  };
 51→
 52→  std::ostringstream oss;
 53→
 54→  oss.str(""); oss << std::setfill('0') << std::setw(4) << (tm_val.tm_year + 1900);
 55→  replace_token("{YYYY}", oss.str());
 56→
 57→  oss.str(""); oss << std::setfill('0') << std::setw(2) << (tm_val.tm_mon + 1);
 58→  replace_token("{MM}", oss.str());
 59→
 60→  oss.str(""); oss << std::setfill('0') << std::setw(2) << tm_val.tm_mday;
 61→  replace_token("{DD}", oss.str());
 62→
 63→  oss.str(""); oss << std::setfill('0') << std::setw(2) << tm_val.tm_hour;
 64→  replace_token("{HH}", oss.str());
 65→
 66→  return pattern;
 67→}
