 69→void OfflineEmissionSource::LoadBrackets(double time_current) {
 70→  std::string file_path = ResolveFilePath(time_current);
 71→
 72→  reader_.Open(file_path, descriptor_);
 73→  inventory_species_ = reader_.QuerySpecies();
 74→
 75→  auto times = reader_.GetTimeValues();
 76→  int n_cells = reader_.NumCells();
 77→  int n_times = reader_.NumTimeSteps();
 78→
 79→  if (n_times == 0) {
 80→    throw IOError("No time steps in file: " + file_path);
 81→  }
 82→
 83→  // Find bracketing time indices
 84→  int left_idx = 0;
 85→  int right_idx = std::min(1, n_times - 1);
 86→
 87→  if (n_times > 1) {
 88→    bool found_bracket = false;
 89→    for (int t = 0; t < n_times - 1; ++t) {
 90→      if (times[t] <= time_current && time_current <= times[t + 1]) {
 91→        left_idx = t;
 92→        right_idx = t + 1;
 93→        found_bracket = true;
 94→        break;
 95→      }
 96→    }
 97→
 98→    if (!found_bracket) {
 99→      if (time_current > times[n_times - 1]) {
100→        // Climatological wrap-around: bracket between last and first time
101→        // steps, treating data as a repeating annual cycle
102→        left_idx = n_times - 1;
103→        right_idx = 0;
104→      } else if (time_current < times[0]) {
105→        // Before first time step — wrap from last to first
106→        left_idx = n_times - 1;
107→        right_idx = 0;
108→      }
109→    }
110→  }
111→
112→  // Read raw inventory data at bracket times
113→  std::vector<Real> raw_left, raw_right;
114→  int n_cells_read;
115→  reader_.ReadFlux(left_idx, inventory_species_, raw_left, n_cells_read);
116→  reader_.ReadFlux(right_idx, inventory_species_, raw_right, n_cells_read);
117→
118→  // Apply species mapping: inventory → mechanism
119→  std::vector<Real> mapped_left, mapped_right;
120→  species_map_.Apply(raw_left, inventory_species_, mapped_left, n_cells);
121→  species_map_.Apply(raw_right, inventory_species_, mapped_right, n_cells);
122→
123→  // Set interpolator brackets
124→  double time_left = (n_times > 0) ? times[left_idx] : 0.0;
125→  double time_right = (n_times > 1) ? times[right_idx] : time_left + 1.0;
126→
127→  // For climatological wrap-around, adjust right time to be after left
128→  if (right_idx < left_idx && n_times > 1) {
129→    // Estimate cycle period from the time span of the file
130→    double cycle_period = times[n_times - 1] - times[0];
131→    // Add one step interval to approximate the full cycle
132→    if (n_times > 1) {
133→      double avg_step = cycle_period / (n_times - 1);
134→      time_right = times[n_times - 1] + avg_step;
135→    }
136→  }
137→
138→  interpolator_.SetBracket(time_left, time_right, mapped_left, mapped_right);
139→
140→  brackets_loaded_ = true;
141→}
142→
143→void OfflineEmissionSource::Update(double time_current, int n_cells,
144→                                   std::vector<Real>& flux_out,
145→                                   std::vector<std::string>& species_names_out) {
146→  // Load brackets if needed
147→  if (!brackets_loaded_ || !interpolator_.CoversTime(time_current)) {
148→    LoadBrackets(time_current);
149→  }
150→
151→  // Interpolate to current time
152→  std::vector<Real> interpolated;
153→  interpolator_.Interpolate(time_current, interpolated);
154→
155→  species_names_out = mechanism_species_;
156→  int n_mech = static_cast<int>(mechanism_species_.size());
157→
158→  // Validate cell count consistency
159→  size_t expected_size = static_cast<size_t>(n_mech) * n_cells;
160→  if (!interpolated.empty() && interpolated.size() != expected_size) {
161→    throw ValidationError(
162→        "OfflineEmissionSource '" + name_ + "': cell count mismatch — "
163→        "file has " + std::to_string(interpolated.size() / n_mech) +
164→        " cells but host expects " + std::to_string(n_cells));
165→  }
166→
167→  // Accumulate into flux_out
168→  flux_out.resize(expected_size, 0.0);
169→  for (size_t i = 0; i < interpolated.size(); ++i) {
170→    flux_out[i] += interpolated[i];
171→  }
172→}
