 58→void CreateSESFile(const std::string& path, int n_cells = 4) {
 59→  int ncid;
 60→  nc_create(path.c_str(), NC_CLOBBER | NC_NETCDF4, &ncid);
 61→  nc_put_att_text(ncid, NC_GLOBAL, "ses_version", 3, "1.0");
 62→  nc_put_att_text(ncid, NC_GLOBAL, "Conventions", 4, "CF-1.8");
 63→
 64→  int time_dim, cell_dim;
 65→  nc_def_dim(ncid, "time", 1, &time_dim);
 66→  nc_def_dim(ncid, "n_cells", static_cast<size_t>(n_cells), &cell_dim);
 67→
 68→  int time_varid;
 69→  nc_def_var(ncid, "time", NC_DOUBLE, 1, &time_dim, &time_varid);
 70→  const char* units = "seconds since 1970-01-01";
 71→  nc_put_att_text(ncid, time_varid, "units", std::strlen(units), units);
 72→
 73→  int dims2d[2] = {time_dim, cell_dim};
 74→  int nox_varid;
 75→  nc_def_var(ncid, "emi_NOx", NC_DOUBLE, 2, dims2d, &nox_varid);
 76→
 77→  nc_enddef(ncid);
 78→
 79→  double time_val = 0.0;
 80→  nc_put_var_double(ncid, time_varid, &time_val);
 81→
 82→  std::vector<double> flux(n_cells, 1.0e-6);
 83→  nc_put_var_double(ncid, nox_varid, flux.data());
 84→  nc_close(ncid);
 85→}
 86→
 87→}  // namespace
