 13→SpeciesMap::SpeciesMap(const std::string& yaml_path) {
 14→  YAML::Node root;
 15→  try {
 16→    root = YAML::LoadFile(yaml_path);
 17→  } catch (const YAML::Exception& e) {
 18→    throw ConfigError("Failed to load species map: " + yaml_path +
 19→                      " — " + e.what());
 20→  }
 21→
 22→  auto species_map_node = root["species_map"];
 23→  if (!species_map_node) {
 24→    throw ConfigError("Missing 'species_map' key in: " + yaml_path);
 25→  }
 26→
 27→  if (species_map_node["mechanism"]) {
 28→    mechanism_name_ = species_map_node["mechanism"].as<std::string>();
 29→  }
 30→
 31→  auto mappings_node = species_map_node["mappings"];
 32→  if (!mappings_node || !mappings_node.IsSequence()) {
 33→    throw ConfigError("Missing or invalid 'mappings' in: " + yaml_path);
 34→  }
 35→
 36→  // Track scaling factor sums per inventory species for warnings
 37→  std::map<std::string, Real> scaling_sums;
 38→
 39→  for (const auto& entry : mappings_node) {
 40→    SpeciesMapping mapping;
 41→    mapping.inventory_name = entry["inventory"].as<std::string>();
 42→    mapping.mechanism_name = entry["mechanism"].as<std::string>();
 43→    mapping.scaling_factor = entry["scaling"]
 44→        ? entry["scaling"].as<Real>()
 45→        : 1.0;
 46→
 47→    scaling_sums[mapping.inventory_name] += mapping.scaling_factor;
 48→    mappings_.push_back(std::move(mapping));
 49→  }
 50→
 51→  // Validate scaling factors — amplification (>1) is likely a config error
 52→  for (const auto& [name, total] : scaling_sums) {
 53→    if (total > 1.0 + 1e-6) {
 54→      throw ConfigError(
 55→          "Species map: scaling factors for inventory species '" + name +
 56→          "' sum to " + std::to_string(total) +
 57→          " (>1.0) — mass would be amplified. Check species_map YAML.");
 58→    }
 59→  }
 60→
 61→  RebuildCache();
 62→}
 63→
 64→void SpeciesMap::AddMapping(const std::string& inventory_name,
 65→                            const std::string& mechanism_name,
 66→                            Real scaling_factor) {
 67→  mappings_.push_back({inventory_name, mechanism_name, scaling_factor});
 68→  RebuildCache();
 69→}
 70→
 71→void SpeciesMap::RebuildCache() {
 72→  std::set<std::string> unique;
 73→  for (const auto& m : mappings_) {
 74→    unique.insert(m.mechanism_name);
 75→  }
 76→  cached_mechanism_species_ = {unique.begin(), unique.end()};
 77→
 78→  cached_mech_idx_.clear();
 79→  for (int i = 0; i < static_cast<int>(cached_mechanism_species_.size()); ++i) {
 80→    cached_mech_idx_[cached_mechanism_species_[i]] = i;
 81→  }
 82→}
 83→
 84→std::vector<std::string> SpeciesMap::MechanismSpecies() const {
 85→  return cached_mechanism_species_;
 86→}
 87→
 88→std::vector<std::string> SpeciesMap::InventorySpecies() const {
 89→  std::set<std::string> unique;
 90→  for (const auto& m : mappings_) {
 91→    unique.insert(m.inventory_name);
 92→  }
 93→  return {unique.begin(), unique.end()};
 94→}
 95→
 96→void SpeciesMap::Apply(const std::vector<Real>& inventory_flux,
 97→                       const std::vector<std::string>& inventory_names,
 98→                       std::vector<Real>& mechanism_flux,
 99→                       int n_cells) const {
100→  // Build inventory species index (caller-provided, varies per call)
101→  std::map<std::string, int> inv_idx;
102→  for (int i = 0; i < static_cast<int>(inventory_names.size()); ++i) {
103→    inv_idx[inventory_names[i]] = i;
104→  }
105→
106→  // Resize and zero output (using cached mechanism species count)
107→  mechanism_flux.assign(cached_mechanism_species_.size() * n_cells, 0.0);
108→
109→  // Apply each mapping using cached mechanism index
110→  for (const auto& mapping : mappings_) {
111→    auto inv_it = inv_idx.find(mapping.inventory_name);
112→    auto mech_it = cached_mech_idx_.find(mapping.mechanism_name);
113→    if (inv_it == inv_idx.end() || mech_it == cached_mech_idx_.end()) {
114→      continue;
115→    }
116→
117→    int src_row = inv_it->second;
118→    int dst_row = mech_it->second;
119→
120→    for (int ic = 0; ic < n_cells; ++ic) {
121→      mechanism_flux[dst_row * n_cells + ic] +=
122→          inventory_flux[src_row * n_cells + ic] * mapping.scaling_factor;
123→    }
124→  }
125→}
