 8→
 9→Real FluxConverter::FluxToTendency(Real flux_kg_m2_s,
10→                                   Real air_density_kg_m3,
11→                                   Real layer_thickness_m) {
12→  if (air_density_kg_m3 <= 0.0 || layer_thickness_m <= 0.0) {
13→    return 0.0;
14→  }
15→  return flux_kg_m2_s / (air_density_kg_m3 * layer_thickness_m);
16→}
17→
18→void FluxConverter::Convert(EmisState& state,
19→                            const Real* air_density,
20→                            const Real* layer_thickness,
21→                            int n_atm_elements) {
22→  const int n_sp = state.n_species;
23→  const int n_cells = state.n_cells;
24→  const int n_vl = state.n_vert_levels;
25→
26→  if (n_atm_elements < n_vl * n_cells) {
27→    throw ValidationError(
28→        "FluxConverter: air_density and layer_thickness must have at least "
29→        "n_vert_levels * n_cells elements");
30→  }
31→
32→  // Zero tendency before accumulating
33→  std::fill(state.tendency.begin(), state.tendency.end(), 0.0);
34→
35→  for (int isp = 0; isp < n_sp; ++isp) {
36→    int layer = state.injection_layer[isp];
37→    if (layer < 0 || layer >= n_vl) {
38→      layer = 0;  // Default to surface
39→    }
40→
41→    for (int ic = 0; ic < n_cells; ++ic) {
42→      Real flux = state.surface_flux[isp * n_cells + ic];
43→      Real rho = air_density[layer * n_cells + ic];
44→      Real dz = layer_thickness[layer * n_cells + ic];
45→
46→      // tendency index: [species * n_vert_levels * n_cells + level * n_cells + cell]
47→      size_t tend_idx =
48→          static_cast<size_t>(isp) * n_vl * n_cells + layer * n_cells + ic;
49→      state.tendency[tend_idx] = FluxToTendency(flux, rho, dz);
50→    }
51→  }
52→}
