13→DatasetDescriptor DatasetDescriptor::FromYAML(const std::string& yaml_path) {
14→  YAML::Node root;
15→  try {
16→    root = YAML::LoadFile(yaml_path);
17→  } catch (const YAML::Exception& e) {
18→    throw ConfigError("Failed to load descriptor: " + yaml_path +
19→                      " — " + e.what());
20→  }
21→
22→  auto desc_node = root["descriptor"];
23→  if (!desc_node) {
24→    throw ConfigError("Missing 'descriptor' key in: " + yaml_path);
25→  }
26→
27→  DatasetDescriptor desc;
28→
29→  if (desc_node["variable_prefix"]) {
30→    desc.variable_prefix = desc_node["variable_prefix"].as<std::string>();
31→  }
32→  if (desc_node["flux_units"]) {
33→    desc.flux_units = desc_node["flux_units"].as<std::string>();
34→  }
35→  if (desc_node["unit_conversion_factor"]) {
36→    desc.unit_conversion_factor = desc_node["unit_conversion_factor"].as<Real>();
37→  }
38→  if (desc_node["time_dimension"]) {
39→    desc.time_dimension = desc_node["time_dimension"].as<std::string>();
40→  }
41→  if (desc_node["cell_dimension"]) {
42→    desc.cell_dimension = desc_node["cell_dimension"].as<std::string>();
43→  }
44→  if (desc_node["grid_description"]) {
45→    desc.grid_description = desc_node["grid_description"].as<std::string>();
46→  }
47→
48→  if (desc_node["species_rename"]) {
49→    for (const auto& pair : desc_node["species_rename"]) {
50→      desc.species_rename[pair.first.as<std::string>()] =
51→          pair.second.as<std::string>();
52→    }
53→  }
54→
55→  return desc;
