 44→// Create a minimal SES 1.0 compliant NetCDF file with known emission data.
 45→void CreateTestNetCDF(const std::string& path,
 46→                      int n_times, int n_cells,
 47→                      const std::vector<double>& time_values,
 48→                      const std::vector<std::string>& species,
 49→                      const std::vector<std::vector<double>>& flux_data) {
 50→  int ncid;
 51→  int status = nc_create(path.c_str(), NC_CLOBBER | NC_NETCDF4, &ncid);
 52→  if (status != NC_NOERR)
 53→    throw std::runtime_error("nc_create failed: " + std::string(nc_strerror(status)));
 54→
 55→  // Global attributes
 56→  nc_put_att_text(ncid, NC_GLOBAL, "ses_version", 3, "1.0");
 57→  nc_put_att_text(ncid, NC_GLOBAL, "Conventions", 4, "CF-1.8");
 58→
 59→  // Dimensions
 60→  int time_dim, cell_dim;
 61→  nc_def_dim(ncid, "time", static_cast<size_t>(n_times), &time_dim);
 62→  nc_def_dim(ncid, "n_cells", static_cast<size_t>(n_cells), &cell_dim);
 63→
 64→  // Time variable
 65→  int time_varid;
 66→  nc_def_var(ncid, "time", NC_DOUBLE, 1, &time_dim, &time_varid);
 67→  const char* time_units = "seconds since 1970-01-01";
 68→  nc_put_att_text(ncid, time_varid, "units",
 69→                  std::strlen(time_units), time_units);
 70→
 71→  // Species flux variables: (time, n_cells)
 72→  std::vector<int> flux_varids(species.size());
 73→  int dims2d[2] = {time_dim, cell_dim};
 74→  for (size_t i = 0; i < species.size(); ++i) {
 75→    std::string var_name = "emi_" + species[i];
 76→    nc_def_var(ncid, var_name.c_str(), NC_DOUBLE, 2, dims2d, &flux_varids[i]);
 77→  }
 78→
 79→  nc_enddef(ncid);
 80→
 81→  // Write time values
 82→  nc_put_var_double(ncid, time_varid, time_values.data());
 83→
 84→  // Write flux data for each species
 85→  for (size_t i = 0; i < species.size(); ++i) {
 86→    nc_put_var_double(ncid, flux_varids[i], flux_data[i].data());
 87→  }
 88→
 89→  nc_close(ncid);
 90→}
