#pragma once

#include <map>
#include <string>
#include <vector>

#include "miem/util/types.hpp"

namespace miem {

struct EmisState {
  int n_species = 0;
  int n_cells = 0;
  int n_vert_levels = 0;

  // Surface fluxes: (n_species * n_cells) in kg/m^2/s
  // Layout: species-major, i.e. flux[species_idx * n_cells + cell_idx]
  std::vector<Real> surface_flux;

  // Volumetric tendencies: (n_species * n_vert_levels * n_cells) in kg/kg/s
  // Layout: tendency[species_idx * n_vert_levels * n_cells + level_idx * n_cells + cell_idx]
  std::vector<Real> tendency;

  // Maps emission species index to host chemistry species index
  std::vector<int> emis_to_chem_idx;

  // Injection layer for each species (0 = surface)
  std::vector<int> injection_layer;

  // Species names for this emission state
  std::vector<std::string> species_names;

  // Per-sector surface fluxes: sector_name -> (n_species * n_cells) array
  std::map<std::string, std::vector<Real>> sector_fluxes;

  // Sector names in insertion order
  std::vector<std::string> sector_names;

  EmisState() = default;
  EmisState(int n_species, int n_cells, int n_vert_levels);

  void Resize(int n_species, int n_cells, int n_vert_levels);
  void Zero();

  bool HasSectors() const { return !sector_fluxes.empty(); }
  const std::vector<Real>& GetSectorFlux(const std::string& sector) const;

  Real* SurfaceFluxData() { return surface_flux.data(); }
  const Real* SurfaceFluxData() const { return surface_flux.data(); }

  Real* TendencyData() { return tendency.data(); }
  const Real* TendencyData() const { return tendency.data(); }

  int* EmisToChemIdxData() { return emis_to_chem_idx.data(); }
  const int* EmisToChemIdxData() const { return emis_to_chem_idx.data(); }
};

}  // namespace miem

# Standardized Emissions Schema (SES) 1.0

## Overview

SES defines the NetCDF convention for emission input files consumed by MIEM.
Files conforming to this schema are processed without a DatasetDescriptor;
non-conforming files require a descriptor to map their layout to SES conventions.

## Dimensions

| Dimension | Meaning | Notes |
|-----------|---------|-------|
| `n_cells` | Spatial cells (host-grid-aligned, 1D) | Required |
| `time` | Time steps | Required, unlimited |

## Global Attributes

| Attribute | Type | Required | Example |
|-----------|------|----------|---------|
| `ses_version` | string | **Yes** | `"1.0"` |
| `Conventions` | string | **Yes** | `"CF-1.8"` |
| `grid_description` | string | Recommended | `"CAM-SE ne30np4"` |
| `source_inventory` | string | Recommended | `"CEDSv2024-04"` |
| `preprocessing_tool_version` | string | Recommended | `"UPTEMPO 0.1.0"` |

## Time Coordinate

- Variable name: `time`
- Must have a `units` attribute in CF format: e.g., `"days since 2000-01-01"`
- Calendar attribute recommended: `calendar = "standard"`

## Emission Variables

- Naming: `emi_<species>(time, n_cells)` — e.g., `emi_NOx`, `emi_SO2`
- Required `units` attribute: `"kg m-2 s-1"`
- Optional `_FillValue` attribute (masked to 0.0 by reader)
- Compression recommendation: `deflate_level=1`

## Example (CDL)

```
netcdf example_ses {
dimensions:
    n_cells = 48602 ;
    time = UNLIMITED ;
variables:
    double time(time) ;
        time:units = "days since 2000-01-01" ;
        time:calendar = "standard" ;
    double emi_NOx(time, n_cells) ;
        emi_NOx:units = "kg m-2 s-1" ;
    double emi_SO2(time, n_cells) ;
        emi_SO2:units = "kg m-2 s-1" ;

// global attributes:
    :ses_version = "1.0" ;
    :Conventions = "CF-1.8" ;
    :source_inventory = "CEDSv2024-04" ;
    :grid_description = "CAM-SE ne30np4" ;
}
```
